window.wordsData = {
  list: WORDS_DATABASE,
  categories: WORDS_CATEGORIES,

  getByLetter(letter) {
    if (!letter || letter === 'ALL') return this.list;
    const l = letter.toUpperCase();
    return this.list.filter(item => item.l === l);
  },

  getByCategory(cat) {
    if (!cat || cat === 'all') return this.list;
    return this.list.filter(item => item.cat === cat);
  },

  search(keyword) {
    if (!keyword) return this.list;
    const q = keyword.trim().toLowerCase();
    return this.list.filter(item => item.w.toLowerCase().includes(q) || item.zh.includes(q));
  },

  getRandom(count = 4, excludeWord = '') {
    const pool = excludeWord ? this.list.filter(item => item.w !== excludeWord) : [...this.list];
    for (let i = pool.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [pool[i], pool[j]] = [pool[j], pool[i]];
    }
    return pool.slice(0, count);
  },

  generateQuiz(type = 'en-to-zh', filterCategory = 'all') {
    let pool = filterCategory === 'all' ? this.list : this.getByCategory(filterCategory);
    if (!pool || pool.length < 4) pool = this.list;

    const targetIndex = Math.floor(Math.random() * pool.length);
    const target = pool[targetIndex];

    const distractors = this.getRandom(3, target.w);
    const options = [target, ...distractors];

    for (let i = options.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [options[i], options[j]] = [options[j], options[i]];
    }

    return {
      type, // 'en-to-zh', 'zh-to-en', 'listening'
      target,
      options,
      correctIndex: options.findIndex(o => o.w === target.w)
    };
  }
};
